const SOL_JANUS = 'common-sol-janus'
const SOL_HECATE = 'common-sol-hecate'

function paint(skill: JobHexaCatalog['skills'][number], url: string | null | undefined) {
  if (skill.iconUrl || !url) return skill
  return { ...skill, iconUrl: url }
}

/** 既にアイコンがあるスキルはそのまま残し、空いている枠だけナムウィキの画像を入れる。 */
export function withNamuIcons(catalog: JobHexaCatalog): JobHexaCatalog {
  const icons = NAMU_JOB_ICONS[catalog.jobId]
  if (!icons) return catalog

  let masteryIndex = 0
  let enhanceIndex = 0
  let sharedUsed = false
  const skills = catalog.skills.map((skill) => {
    if (skill.role === 'origin') return paint(skill, icons.s[0])
    if (skill.role === 'ascent') return paint(skill, icons.s[1])
    if (skill.role === 'boost') return paint(skill, icons.s[2])
    if (skill.kind === 'mastery-core') {
      const url = icons.m[masteryIndex]
      masteryIndex += 1
      return paint(skill, url)
    }
    if (skill.kind === 'enhance-core') {
      const url = icons.e[enhanceIndex]
      enhanceIndex += 1
      return paint(skill, url)
    }
    if (skill.kind === 'common-core' && skill.id !== SOL_JANUS && skill.id !== SOL_HECATE) {
      if (sharedUsed) return skill
      sharedUsed = true
      return paint(skill, icons.c)
    }
    return skill
  })

  return { ...catalog, skills }
}
